Because safe Rust requires careful handling of ownership, we use `Option<Box<Node>>` to represent the pointers.

```rust
// Definition for a singly-linked list node.
#[derive(PartialEq, Eq, Clone, Debug)]
pub struct ListNode {
    pub val: i32,
    pub next: Option<Box<ListNode>>,
}

impl ListNode {
    #[inline]
    pub fn new(val: i32) -> Self {
        ListNode { next: None, val }
    }
}

/// Reverses a singly-linked list iteratively.
pub fn reverse_list(mut head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    let mut prev = None;

    // While there is still a node to process
    while let Some(mut current) = head {
        // 1. Temporarily extract the rest of the list, 
        //    leaving head as the remainder of the list.
        head = current.next.take();

        // 2. Point current's next to the reversed list built so far.
        current.next = prev;

        // 3. Move prev forward to include current.
        prev = Some(current);
    }

    prev
}

fn main() {
    // Helper to create a list: 1 -> 2 -> 3 -> None
    let mut node3 = ListNode::new(3);
    let mut node2 = ListNode::new(2);
    let mut node1 = ListNode::new(1);

    node2.next = Some(Box::new(node3));
    node1.next = Some(Box::new(node2));
    let head = Some(Box::new(node1));

    println!("Original: {:?}", head);

    // Reverse the list: 3 -> 2 -> 1 -> None
    let reversed = reverse_list(head);

    println!("Reversed: {:?}", reversed);
}
