Here is a complete, type-safe implementation of a **Stack** data structure in TypeScript using generics.

### Implementation

```typescript
interface IStack<T> {
  push(item: T): void;
  pop(): T | undefined;
  peek(): T | undefined;
  isEmpty(): boolean;
  size(): number;
  clear(): void;
}

export class Stack<T> implements IStack<T> {
  // Use a private array to store elements
  private items: T[] = [];

  /**
   * Adds an element to the top of the stack.
   * Time Complexity: O(1)
   */
  push(item: T): void {
    this.items.push(item);
  }

  /**
   * Removes and returns the top element of the stack.
   * Returns `undefined` if the stack is empty.
   * Time Complexity: O(1)
   */
  pop(): T | undefined {
    return this.items.pop();
  }

  /**
   * Returns the top element without removing it.
   * Returns `undefined` if the stack is empty.
   * Time Complexity: O(1)
   */
  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /**
   * Checks if the stack is empty.
   * Time Complexity: O(1)
   */
  isEmpty(): boolean {
    return this.items.length === 0;
  }

  /**
   * Returns the total number of elements in the stack.
   * Time Complexity: O(1)
   */
  size(): number {
    return this.items.length;
  }

  /**
   * Removes all elements from the stack.
   * Time Complexity: O(1)
   */
  clear(): void {
    this.items = [];
  }
}
```

